// Fill missing it/ja/hi/am keys from English so the build sees a complete
// Record<Lang, T> while the user-facing surfaces above still get proper
// Italian / Japanese / Hindi / Amharic translations. Same fallback
// principle used by i18n-v2 for de/cs.
for (const key of Object.keys(T.en) as Array<keyof typeof T.en>) {
  if ((T.it as Record<string, unknown>)[key] === undefined) {
    (T.it as Record<string, unknown>)[key] = T.en[key];
  }
  if ((T.ja as Record<string, unknown>)[key] === undefined) {
    (T.ja as Record<string, unknown>)[key] = T.en[key];
  }
  if ((T.hi as Record<string, unknown>)[key] === undefined) {
    (T.hi as Record<string, unknown>)[key] = T.en[key];
  }
  if ((T.am as Record<string, unknown>)[key] === undefined) {
    (T.am as Record<string, unknown>)[key] = T.en[key];
  }
}

